import os
from typing import Any, Dict, List, Optional

import boto3


def extract_document_layout(
    file_path: str,
    feature_types: Optional[List[str]] = None,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    if feature_types is None:
        feature_types = ["TABLES", "FORMS", "LAYOUT"]

    client = boto3.client("textract", region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1")

    with open(file_path, "rb") as f:
        document_bytes = f.read()

    response = client.analyze_document(
        Document={"Bytes": document_bytes},
        FeatureTypes=feature_types,
    )

    blocks = response.get("Blocks", [])
    block_by_id = {block["Id"]: block for block in blocks if "Id" in block}

    pages: Dict[int, Dict[str, Any]] = {}
    lines: List[Dict[str, Any]] = []
    tables: List[Dict[str, Any]] = []
    layout_elements: List[Dict[str, Any]] = []

    def _bbox(block: Dict[str, Any]) -> Optional[Dict[str, float]]:
        geometry = block.get("Geometry", {})
        box = geometry.get("BoundingBox")
        if not box:
            return None
        return {
            "left": box.get("Left", 0.0),
            "top": box.get("Top", 0.0),
            "width": box.get("Width", 0.0),
            "height": box.get("Height", 0.0),
        }

    def _polygon(block: Dict[str, Any]) -> List[Dict[str, float]]:
        geometry = block.get("Geometry", {})
        return [
            {"x": p.get("X", 0.0), "y": p.get("Y", 0.0)}
            for p in geometry.get("Polygon", [])
        ]

    def _confidence(block: Dict[str, Any]) -> Optional[float]:
        return block.get("Confidence")

    def _page_num(block: Dict[str, Any]) -> int:
        return int(block.get("Page", 1))

    def _entity_types(block: Dict[str, Any]) -> List[str]:
        return block.get("EntityTypes", [])

    def _get_child_ids(block: Dict[str, Any], relationship_type: str = "CHILD") -> List[str]:
        ids: List[str] = []
        for rel in block.get("Relationships", []):
            if rel.get("Type") == relationship_type:
                ids.extend(rel.get("Ids", []))
        return ids

    def _get_text_for_block(block: Dict[str, Any]) -> str:
        if "Text" in block:
            return block["Text"]
        texts: List[str] = []
        for child_id in _get_child_ids(block, "CHILD"):
            child = block_by_id.get(child_id, {})
            if child.get("BlockType") == "WORD":
                texts.append(child.get("Text", ""))
            elif child.get("BlockType") == "SELECTION_ELEMENT":
                if child.get("SelectionStatus") == "SELECTED":
                    texts.append("[X]")
                else:
                    texts.append("[ ]")
        return " ".join(t for t in texts if t).strip()

    def _extract_table(table_block: Dict[str, Any]) -> Dict[str, Any]:
        cell_ids = []
        for rel in table_block.get("Relationships", []):
            if rel.get("Type") in ("CHILD", "MERGED_CELL"):
                cell_ids.extend(rel.get("Ids", []))

        cells = []
        max_row = 0
        max_col = 0

        for cell_id in cell_ids:
            cell = block_by_id.get(cell_id)
            if not cell or cell.get("BlockType") not in ("CELL", "MERGED_CELL"):
                continue

            row_index = int(cell.get("RowIndex", 1))
            col_index = int(cell.get("ColumnIndex", 1))
            row_span = int(cell.get("RowSpan", 1))
            col_span = int(cell.get("ColumnSpan", 1))
            text = _get_text_for_block(cell)

            max_row = max(max_row, row_index + row_span - 1)
            max_col = max(max_col, col_index + col_span - 1)

            cells.append(
                {
                    "id": cell.get("Id"),
                    "row_index": row_index,
                    "column_index": col_index,
                    "row_span": row_span,
                    "column_span": col_span,
                    "text": text,
                    "confidence": _confidence(cell),
                    "bbox": _bbox(cell),
                    "polygon": _polygon(cell),
                    "entity_types": _entity_types(cell),
                }
            )

        grid = [["" for _ in range(max_col)] for _ in range(max_row)]
        for cell in cells:
            r = cell["row_index"] - 1
            c = cell["column_index"] - 1
            if 0 <= r < max_row and 0 <= c < max_col:
                grid[r][c] = cell["text"]

        return {
            "id": table_block.get("Id"),
            "page": _page_num(table_block),
            "confidence": _confidence(table_block),
            "bbox": _bbox(table_block),
            "polygon": _polygon(table_block),
            "entity_types": _entity_types(table_block),
            "rows": max_row,
            "columns": max_col,
            "cells": cells,
            "grid": grid,
        }

    for block in blocks:
        page_number = _page_num(block)
        pages.setdefault(
            page_number,
            {
                "page": page_number,
                "width": None,
                "height": None,
                "lines": [],
                "tables": [],
                "layout": [],
            },
        )

        block_type = block.get("BlockType")

        if block_type == "PAGE":
            box = _bbox(block)
            if box:
                pages[page_number]["width"] = box["width"]
                pages[page_number]["height"] = box["height"]

        elif block_type == "LINE":
            line = {
                "id": block.get("Id"),
                "page": page_number,
                "text": block.get("Text", ""),
                "confidence": _confidence(block),
                "bbox": _bbox(block),
                "polygon": _polygon(block),
            }
            lines.append(line)
            pages[page_number]["lines"].append(line)

        elif block_type == "TABLE":
            table = _extract_table(block)
            tables.append(table)
            pages[page_number]["tables"].append(table)

        elif block_type in {
            "LAYOUT_TEXT",
            "LAYOUT_TITLE",
            "LAYOUT_HEADER",
            "LAYOUT_FOOTER",
            "LAYOUT_SECTION_HEADER",
            "LAYOUT_PAGE_NUMBER",
            "LAYOUT_LIST",
            "LAYOUT_FIGURE",
            "LAYOUT_TABLE",
            "LAYOUT_KEY_VALUE",
        }:
            item = {
                "id": block.get("Id"),
                "type": block_type,
                "page": page_number,
                "text": _get_text_for_block(block),
                "confidence": _confidence(block),
                "bbox": _bbox(block),
                "polygon": _polygon(block),
                "entity_types": _entity_types(block),
            }
            layout_elements.append(item)
            pages[page_number]["layout"].append(item)

    return {
        "provider": "amazon-textract",
        "api": "boto3.client('textract').analyze_document",
        "feature_types": feature_types,
        "pages": [pages[k] for k in sorted(pages)],
        "blocks": blocks,
        "lines": lines,
        "tables": tables,
        "layout_elements": layout_elements,
        "raw_response": response,
    }
